hooks.command:
if [ -f "${CLAUDE_PLUGIN_ROOT}/scripts/loom_checker.py" ]; then exec python3 "${CLAUDE_PLUGIN_ROOT}/scripts/loom_checker.py" push --hook; else exec python3 -c 'import json, os, re, sys
checker = sys.argv[1]
failed = f"installed checker is unavailable at {checker}; restart Claude Code to load the installed plugin version"
store = [re.compile(r"loom/selections/"), re.compile(r"\.git/loom")]
text = store + [re.compile(r"(?<![\w.-])selections/"), re.compile(r"git-common-dir|--git-dir|\bGIT_DIR\b")]
def deny(why):
 print(f"BLOCK selection.guard: {why} ({failed})", file=sys.stderr)
 raise SystemExit(2)
try:
 payload = json.load(sys.stdin)
 fields = {k: v for k, v in (payload.get("tool_input") or {}).items() if isinstance(v, str)}
 cwd = str(payload.get("cwd") or os.getcwd())
except (ValueError, TypeError, AttributeError):
 deny("hook payload is unreadable")
if payload.get("tool_name") in {"Write", "Edit", "MultiEdit", "NotebookEdit", "apply_patch"}:
 targets = [v for k, v in fields.items() if k in {"file_path", "notebook_path"}]
 targets += [t for v in fields.values() for t in re.findall(r"^\*\*\* (?:Add File|Update File|Delete File|Move to): (.+?)\s*$", v, re.M)]
 if any(p.search(os.path.normpath(os.path.join(cwd, t)) + "/") for t in targets for p in store): deny("targets the selection record store")
 raise SystemExit(0)
if any(p.search(os.path.normpath(cwd) + "/") for p in store): deny("runs inside the selection record store")
if any(p.search(fields.get("command", "")) for p in text): deny("names the selection record store")
print(f"loom: publication hook failed ({failed}); allowing.", file=sys.stderr)' "${CLAUDE_PLUGIN_ROOT}/scripts/loom_checker.py"; fi
